import json, sys
data = json.load(sys.stdin)
for e in data[:30]:
    print(f'id={e[\"entry_id\"]} hw={e[\"headword\"][:60]} root={e[\"root\"]} src={e[\"dict_source_type\"]}')
    defn = (e.get('definitions_text') or '')[:150]
    if defn: print(f'  def: {defn}')
    tr = e.get('translation_en') or ''
    if tr: print(f'  en: {tr}')
